DROP TABLE IF EXISTS `hrm_employee_change_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_employee_change_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '异动记录编号',
  `employee_id` bigint NOT NULL COMMENT '员工编号',
  `type` tinyint DEFAULT NULL COMMENT '变动类型',
  `reason` tinyint DEFAULT NULL COMMENT '异动原因',
  `old_dept_id` bigint DEFAULT NULL COMMENT '原部门编号',
  `new_dept_id` bigint DEFAULT NULL COMMENT '新部门编号',
  `old_post_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原岗位名称',
  `new_post_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '新岗位名称',
  `old_post_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原职级',
  `new_post_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '新职级',
  `old_work_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原工作地点',
  `new_work_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '新工作地点',
  `old_leader_employee_id` bigint DEFAULT NULL COMMENT '原直属上级员工编号',
  `new_leader_employee_id` bigint DEFAULT NULL COMMENT '新直属上级员工编号',
  `probation` int DEFAULT NULL COMMENT '试用期',
  `effect_time` datetime DEFAULT NULL COMMENT '生效时间',
  `applied_time` datetime DEFAULT NULL COMMENT '实际生效时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_hrm_employee_change_employee_id` (`employee_id`) USING BTREE,
  KEY `idx_hrm_employee_change_apply_type_effect` (`applied_time`,`type`,`effect_time`) USING BTREE,
  KEY `idx_hrm_employee_change_employee_effect` (`employee_id`,`effect_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 员工异动记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

