DROP TABLE IF EXISTS `hrm_performance_assessment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_performance_assessment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `plan_id` bigint NOT NULL COMMENT '计划编号',
  `employee_id` bigint NOT NULL COMMENT '员工编号',
  `status` tinyint DEFAULT '2' COMMENT '考核状态',
  `process_status` tinyint DEFAULT '1' COMMENT '流程处理状态：1 进行中，2 已完成',
  `stage_type` tinyint DEFAULT '0' COMMENT '当前业务阶段类型',
  `stage_sort` int DEFAULT '0' COMMENT '阶段排序',
  `score` decimal(10,2) DEFAULT '0.00' COMMENT '得分',
  `result_level` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结果等级',
  `coefficient` decimal(10,2) DEFAULT '1.00' COMMENT '绩效系数',
  `target_confirmation_result` tinyint DEFAULT NULL COMMENT '目标确认结果：0 驳回，1 通过',
  `target_confirmation_comment` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标确认意见',
  `target_confirmation_time` datetime DEFAULT NULL COMMENT '目标确认时间',
  `self_comment` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '自评说明',
  `reviewer_comment` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '评分说明',
  `result_comment` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结果说明',
  `result_confirmation_time` datetime DEFAULT NULL COMMENT '结果确认时间',
  `result_audit_status` tinyint DEFAULT NULL COMMENT '结果审核状态：1 审批中，2 通过，3 驳回，4 取消',
  `result_audit_time` datetime DEFAULT NULL COMMENT '结果审核完成时间',
  `result_audit_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结果审核意见',
  `appeal_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申诉原因',
  `appeal_file_urls` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申诉附件地址列表',
  `appeal_submit_time` datetime DEFAULT NULL COMMENT '申诉提交时间',
  `appeal_status` tinyint DEFAULT '0' COMMENT '申诉状态',
  `appeal_time` datetime DEFAULT NULL COMMENT '申诉完成时间',
  `appeal_comment` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申诉审批意见',
  `archive_time` datetime DEFAULT NULL COMMENT '归档时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_hrm_performance_assessment_employee_id` (`employee_id`) USING BTREE,
  KEY `idx_hrm_performance_assessment_plan_employee` (`plan_id`,`employee_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=111 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 员工绩效考核表';
/*!40101 SET character_set_client = @saved_cs_client */;

