  `weight` decimal(10,2) DEFAULT NULL COMMENT '评分权重快照',
  `scoring_type` tinyint DEFAULT NULL COMMENT '评分方式',
  `visible_content` tinyint DEFAULT NULL COMMENT '可见内容',
  `required_setting` bit(1) DEFAULT NULL COMMENT '评语是否必填',
  `reject_authority` bit(1) DEFAULT NULL COMMENT '是否允许驳回',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0 未处理，1 已处理，2 待处理，3 已驳回，4 处理中，5 已申诉',
  `score` decimal(10,2) DEFAULT NULL COMMENT '阶段综合得分',
