INSERT INTO `hrm_performance_assessment_template` VALUES (1,'员工端演示 KPI 模板','用于 admin 员工端绩效演示',1,1,100.00,1,3,'[{\"name\": \"工作目标\", \"quotas\": [{\"name\": \"项目交付\", \"weight\": 40.0, \"standard\": \"按期交付且质量达标\", \"scoreType\": 1, \"illustrate\": \"完成核心项目里程碑\"}, {\"name\": \"质量改进\", \"weight\": 35.0, \"standard\": \"关键缺陷闭环率达到 95%\", \"scoreType\": 1, \"illustrate\": \"降低线上缺陷并推进复盘\"}, {\"name\": \"团队协作\", \"weight\": 25.0, \"standard\": \"完成至少 2 次分享或评审\", \"scoreType\": 1, \"illustrate\": \"支持跨团队协作与知识分享\"}], \"remark\": \"员工端演示绩效维度\", \"weight\": 100.0, \"allowEdit\": true, \"quotaType\": 1}]',0,'1','2026-07-27 08:00:49','1','2026-07-27 08:19:44',0x00,1),(2,'浏览器冒烟 KPI 模板','用于验证新增、修改和考核维度弹窗（已修改）',1,1,100.00,1,1,'[{\"name\": \"冒烟维度\", \"quotas\": [{\"name\": \"冒烟指标\", \"weight\": 100, \"standard\": \"完成冒烟验证\", \"scoreType\": 1, \"illustrate\": \"验证绩效指标填写\"}], \"remark\": null, \"weight\": 100, \"allowEdit\": false, \"quotaType\": 1}]',0,'1','2026-07-27 16:21:59','1','2026-07-30 21:24:23',0x01,1),(3,'API自测-1785339849950-考核模板','已修改',1,1,100.00,1,1,'[{\"name\": \"接口维度\", \"quotas\": [{\"name\": \"接口指标\", \"weight\": 100, \"standard\": \"达到预期\", \"scoreType\": 1, \"illustrate\": \"接口自测\"}], \"remark\": \"接口自测\", \"weight\": 100, \"allowEdit\": false, \"quotaType\": 1}]',0,'1','2026-07-29 23:44:10','1','2026-07-29 23:44:10',0x01,1),(4,'API自测-1785339849950-批量考核-1','全接口自动化验证',1,1,100.00,1,1,'[{\"name\": \"接口维度\", \"quotas\": [{\"name\": \"接口指标\", \"weight\": 100, \"standard\": \"达到预期\", \"scoreType\": 1, \"illustrate\": \"接口自测\"}], \"remark\": \"接口自测\", \"weight\": 100, \"allowEdit\": false, \"quotaType\": 1}]',0,'1','2026-07-29 23:44:10','1','2026-07-29 23:44:10',0x01,1),(5,'API自测-1785339849950-批量考核-2','全接口自动化验证',1,1,100.00,1,1,'[{\"name\": \"接口维度\", \"quotas\": [{\"name\": \"接口指标\", \"weight\": 100, \"standard\": \"达到预期\", \"scoreType\": 1, \"illustrate\": \"接口自测\"}], \"remark\": \"接口自测\", \"weight\": 100, \"allowEdit\": false, \"quotaType\": 1}]',0,'1','2026-07-29 23:44:10