INSERT INTO `hrm_recruit_company_profile` VALUES (1,'秦川化工产业园发展有限公司','秦川化工产业园','/admin-api/hrm/recruit/company/file/logo-2020-49435abd51c74dc0be47f4128de6f6e4.png','防腐保温','100-500人','民营','秦川化工产业园发展有限公司，专注于化工园区防腐保温工程施工、材料研发与技术服务。公司拥有专业施工团队与完善的质量管理体系，主要面向化工、石化行业提供设备防腐、管道保温、地坪防护等一站式解决方案。坚持安全为本、品质优先，已与多家化工企业建立长期稳定合作关系。','[{\"name\":\"化工设备防腐工程\",\"intro\":\"提供工业管道保温施工服务，涵盖管道保温层安装、防护外壳包覆、阀门及异型部位保温处理等。公司根据管道介质、温度区间和现场环境选择岩棉、硅酸铝、聚氨酯等保温材料，减少热损失，防止管道结露、冻裂和表面烫伤，满足化工园区管道系统的安全运行与节能要求。\",\"image\":\"\"},{\"name\":\"工业管道保温施工\",\"intro\":\"公司供应防腐保温相关材料，包括防腐涂料、底漆、面漆、保温岩棉板、保温管壳、防护卷材、密封胶带及辅助施工材料等。产品适用于化工设备、工业管道、钢结构及混凝土表面的防腐保温工程，可根据项目工况提供材料选型建议，保障材料性能与施工需求匹配。\",\"image\":\"\"},{\"name\":\"防腐保温材料供应\",\"intro\":\"提供防腐技术咨询服务，包括腐蚀工况分析、涂层体系设计、保温方案优化、施工技术指导和验收标准咨询等。公司结合化工园区设备与管道运行环境，为客户制定更合理的防腐保温方案，帮助提升工程质量、降低后期维护风险，并为项目管理提供技术支持。\",\"image\":\"\"}]','[]','甘肃省兰州市兰州新区秦川化工产业园',NULL,NULL,NULL,'https://www.qinchuan-chem.com','2018-05-12','2000 万元人民币','91620100MA74H28K6D','王建军','企查查','https://www.qcc.com/',0x00,0,0,'81038','2026-09-24 15:03:12','81038','2026-09-24 16:38:50',0x00,2020),(2,'天信管业科技集团有限公司','天信管业','','防腐保温','100-500 人','民营','天信管业科技集团有限公司坐落于陕西省延安市安塞高新技术产业开发区，2014 年成立，占地 83 亩。公司建有标准化厂房、数字化调度中心与延安市防腐保温重点实验室，专注管道防腐、保温保冷工程，防腐新材料研发、石油管道修复再制造、管道检测技术服务。拥有多条自动化生产线，可承接直径 2 米以内管道 3PE 防腐、环氧粉末防腐、夹克保温等业务，具备完善的质量管控体系，为油气、化工行业提供管道全生命周期防腐保温解决方案。','[{\"name\":\"管道防腐工程\",\"intro\":\"可承接直径 2 米以内管道 3PE 防腐、内减阻、环氧酚醛、环氧粉末防腐以及各类弯管防腐作业，采用自动化生产线施工，适用于油气、化工长输管线，提升管道抗腐蚀能力，延长管线使用寿命。\",\"image\":\"\"},{\"name\":\"工业管道保温保冷施工\",\"intro\":\"提供一步法、二步法夹克保温，厂内预制及现场保冷施工服务，针对高温、低温介质管道定制保温保冷方案，降低介质损耗，防止管道结露冻损，满足油田、化工园区管线运行要求。\",\"image\":\"\"},{\"name\":\"防腐保温材料研发与供应\",\"intro\":\"自主研发生产防腐涂料、高分子内衬材料、保温隔热材料，配套各类管道防腐保温辅材，可根据项目工况定制材料选型，保障工程材料品质稳定。\",\"image\":\"\"},{\"name\":\"石油管道修复再制造与管道检测技术服务\",\"intro\":\"开展超高分子聚乙烯油管内衬防腐、旧油管修复再制造业务；配套管道检测、腐蚀工况评估，为油气田老旧管线提供检测评估、修复一体化技术服务。\",\"image\":\"\"}]','[]','陕西省延安市安塞高新技术产业开发区',NULL,NULL,NULL,'http://www.txgyjt.com/','2014-01-10','10000 万元人民币','916106000882410867','闫文科','企业官网','http://www.txgyjt.com/',0x00,0,0,'81006','2026-09-24 15:26:01','81007','2026-09-24 16:10:04',0x00,2025),(3,'隆达橡塑材料股份有限公司','隆达橡塑','/admin-api/hrm/recruit/company/file/logo-1-f9bf57b87168488f86695d178d872d8a.png',NULL,NULL,NULL,NULL,'[]','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0x00,0,0,'1','2026-09-24 16:40:23','1','2026-09-24 16:46:34',0x00,1);
