CREATE TABLE `hrm_recruit_interview` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '面试编号',
  `application_id` bigint DEFAULT NULL COMMENT 'åº”è˜è®°å½•ç¼–å·',
  `candidate_id` bigint NOT NULL COMMENT '候选人编号',
  `type` tinyint DEFAULT NULL COMMENT '面试方式：1 现场面试，2 电话面试，3 视频面试',
  `stage_number` int DEFAULT NULL COMMENT '面试轮次',
  `round_no` int DEFAULT NULL COMMENT 'åº”è˜å†…é¢è¯•è½®æ¬¡',
  `interview_employee_id` bigint DEFAULT NULL COMMENT '主面试官员工编号',
  `other_interview_employee_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '其他面试官员工编号，逗号分隔',
  `interview_time` datetime DEFAULT NULL COMMENT '面试时间',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '面试地址',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `result` tinyint DEFAULT NULL COMMENT '面试结果：1 未完成，2 通过，3 未通过，4 取消',
  `evaluate` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '评价',
  `cancel_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '取消原因',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_hrm_recruit_interview_candidate_id` (`candidate_id`) USING BTREE,
  KEY `idx_hrm_recruit_interview_candidate_stage` (`candidate_id`,`stage_number`) USING BTREE,
  KEY `idx_hrm_recruit_interview_time` (`interview_time`) USING BTREE,
  KEY `idx_recruit_interview_application` (`application_id`,`round_no`)
) ENGINE=InnoDB AUTO_INCREMENT=3033 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 招聘面试表';
